`ifndef LAB1_IMUL_INT_MUL_BASE_V
`define LAB1_IMUL_INT_MUL_BASE_V

`include "vc/muxes.v"
`include "vc/trace.v"

//========================================================================
// Datapath
//========================================================================

module lab1_imul_IntMulBaseDpath
(
  input  logic        clk,
  input  logic        reset,

  input  logic [63:0] istream_msg,
  output logic [31:0] ostream_msg,

  // Control signals from the control unit

  input  logic        a_mux_sel,
  input  logic        b_mux_sel,
  input  logic        result_mux_sel,
  input  logic        add_mux_sel,
  input  logic        result_en,

  // Status signal to the control unit

  output logic        b_lsb,

  // Internal values exported for line tracing

  output logic [31:0] a_reg_out,
  output logic [31:0] b_reg_out,
  output logic [31:0] result_reg_out
);

  //--------------------------------------------------------------------
  // A operand path
  //--------------------------------------------------------------------

  logic [31:0] a_mux_out;
  logic [31:0] a_shift_out;

  vc_Mux2#(32) a_mux
  (
    .in0 (istream_msg[63:32]),
    .in1 (a_shift_out),
    .sel (a_mux_sel),
    .out (a_mux_out)
  );

  always_ff @( posedge clk ) begin
    if ( reset ) a_reg_out <= 32'b0;
    else         a_reg_out <= a_mux_out;
  end

  // Shift A left by one for the next iteration

  assign a_shift_out = a_reg_out << 1;

  //--------------------------------------------------------------------
  // B operand path
  //--------------------------------------------------------------------

  logic [31:0] b_mux_out;
  logic [31:0] b_shift_out;

  vc_Mux2#(32) b_mux
  (
    .in0 (istream_msg[31:0]),
    .in1 (b_shift_out),
    .sel (b_mux_sel),
    .out (b_mux_out)
  );

  always_ff @( posedge clk ) begin
    if ( reset ) b_reg_out <= 32'b0;
    else         b_reg_out <= b_mux_out;
  end

  // Shift B right by one for the next iteration

  assign b_shift_out = b_reg_out >> 1;

  assign b_lsb = b_reg_out[0];

  //--------------------------------------------------------------------
  // Adding Operand path
  //--------------------------------------------------------------------

  logic [31:0] add_out;
  logic [31:0] add_mux_out;
  logic [31:0] result_mux_out;

  assign add_out = a_reg_out + result_reg_out;

  vc_Mux2#(32) add_mux
  (
    .in0 (result_reg_out),
    .in1 (add_out),
    .sel (add_mux_sel),
    .out (add_mux_out)
  );

  //--------------------------------------------------------------------
  // Result path
  //--------------------------------------------------------------------

  vc_Mux2#(32) result_mux
  (
    .in0 (32'b0),
    .in1 (add_mux_out),
    .sel (result_mux_sel),
    .out (result_mux_out)
  );

  always_ff @( posedge clk ) begin
    if      ( reset )     result_reg_out <= 32'b0;
    else if ( result_en ) result_reg_out <= result_mux_out;
  end

  assign ostream_msg = result_reg_out;

endmodule

//========================================================================
// Control Unit
//========================================================================

module lab1_imul_IntMulBaseCtrl
(
  input  logic       clk,
  input  logic       reset,

  input  logic       istream_val,
  output logic       istream_rdy,

  output logic       ostream_val,
  input  logic       ostream_rdy,

  // Status signal from the datapath

  input  logic       b_lsb,

  // Control signals to the datapath

  output logic       a_mux_sel,
  output logic       b_mux_sel,
  output logic       result_mux_sel,
  output logic       add_mux_sel,
  output logic       result_en,

  // Internal values exported for line tracing

  output logic [1:0] status,
  output logic [5:0] counter
);

  localparam logic [1:0] IDLE = 2'd0;
  localparam logic [1:0] CALC = 2'd1;
  localparam logic [1:0] DONE = 2'd2;

  logic [1:0] status_next;
  logic [5:0] counter_next;

  //--------------------------------------------------------------------
  // State elements
  //--------------------------------------------------------------------

  always_ff @( posedge clk ) begin
    if ( reset ) begin
      status  <= IDLE;
      counter <= 6'd0;
    end
    else begin
      status  <= status_next;
      counter <= counter_next;
    end
  end

  //--------------------------------------------------------------------
  // State transitions
  //--------------------------------------------------------------------

  always_comb begin
    status_next = status;

    case ( status )
      IDLE: if ( istream_val )   status_next = CALC;
      CALC: if ( counter == 6'd32 ) status_next = DONE;
      DONE: if ( ostream_rdy )   status_next = IDLE;
      default:                   status_next = IDLE;
    endcase
  end

  //--------------------------------------------------------------------
  // State outputs
  //--------------------------------------------------------------------

  always_comb begin
    istream_rdy    = 1'b0;
    ostream_val    = 1'b0;
    a_mux_sel      = 1'b0;
    b_mux_sel      = 1'b0;
    result_mux_sel = 1'b0;
    add_mux_sel    = 1'b0;
    result_en      = 1'b0;
    counter_next   = counter;

    case ( status )
      IDLE: begin
        istream_rdy  = 1'b1;
        result_en    = 1'b1;
        counter_next = 6'd0;
      end

      CALC: begin
        a_mux_sel      = 1'b1;
        b_mux_sel      = 1'b1;
        result_mux_sel = 1'b1;

        if ( counter < 6'd32 ) begin
          add_mux_sel  = b_lsb;
          result_en    = 1'b1;
          counter_next = counter + 1'b1;
        end
      end

      DONE: begin
        ostream_val = 1'b1;
      end

      default: begin
        counter_next = 6'd0;
      end
    endcase
  end

endmodule

//========================================================================
// Integer Multiplier Fixed-Latency Implementation
//========================================================================

module lab1_imul_IntMulBase
(
  input  logic        clk,
  input  logic        reset,

  input  logic        istream_val,
  output logic        istream_rdy,
  input  logic [63:0] istream_msg,

  output logic        ostream_val,
  input  logic        ostream_rdy,
  output logic [31:0] ostream_msg
);

  // Control/status connections

  logic       a_mux_sel;
  logic       b_mux_sel;
  logic       result_mux_sel;
  logic       add_mux_sel;
  logic       result_en;
  logic       b_lsb;

  // Internal values used by line tracing

  logic [1:0]  status;
  logic [5:0]  counter;
  logic [31:0] a_reg_out;
  logic [31:0] b_reg_out;
  logic [31:0] result_reg_out;

  lab1_imul_IntMulBaseCtrl ctrl
  (
    .clk            (clk),
    .reset          (reset),
    .istream_val    (istream_val),
    .istream_rdy    (istream_rdy),
    .ostream_val    (ostream_val),
    .ostream_rdy    (ostream_rdy),
    .b_lsb          (b_lsb),
    .a_mux_sel      (a_mux_sel),
    .b_mux_sel      (b_mux_sel),
    .result_mux_sel (result_mux_sel),
    .add_mux_sel    (add_mux_sel),
    .result_en      (result_en),
    .status         (status),
    .counter        (counter)
  );

  lab1_imul_IntMulBaseDpath dpath
  (
    .clk            (clk),
    .reset          (reset),
    .istream_msg    (istream_msg),
    .ostream_msg    (ostream_msg),
    .a_mux_sel      (a_mux_sel),
    .b_mux_sel      (b_mux_sel),
    .result_mux_sel (result_mux_sel),
    .add_mux_sel    (add_mux_sel),
    .result_en      (result_en),
    .b_lsb          (b_lsb),
    .a_reg_out      (a_reg_out),
    .b_reg_out      (b_reg_out),
    .result_reg_out (result_reg_out)
  );

  //----------------------------------------------------------------------
  // Line Tracing
  //----------------------------------------------------------------------

  `ifndef SYNTHESIS

  localparam logic [1:0] IDLE = 2'd0;
  localparam logic [1:0] CALC = 2'd1;
  localparam logic [1:0] DONE = 2'd2;

  logic [`VC_TRACE_NBITS-1:0] str;
  `VC_TRACE_BEGIN
  begin

    $sformat( str, "%x", istream_msg );
    vc_trace.append_val_rdy_str( trace_str, istream_val, istream_rdy, str );

    vc_trace.append_str( trace_str, "(" );

    case ( status )
      IDLE:    vc_trace.append_str( trace_str, "IDLE " );
      CALC:    vc_trace.append_str( trace_str, "CALC " );
      DONE:    vc_trace.append_str( trace_str, "DONE " );
      default: vc_trace.append_str( trace_str, "UNKN " );
    endcase

    $sformat( str, "c=%02d a=%x b=%x r=%x",
              counter, a_reg_out, b_reg_out, result_reg_out );
    vc_trace.append_str( trace_str, str );

    vc_trace.append_str( trace_str, ")" );

    $sformat( str, "%x", ostream_msg );
    vc_trace.append_val_rdy_str( trace_str, ostream_val, ostream_rdy, str );

  end
  `VC_TRACE_END

  `endif /* SYNTHESIS */

endmodule

