//=========================================================================
// Integer Multiplier Variable-Latency Implementation
//=========================================================================

`ifndef LAB1_IMUL_INT_MUL_ALT_V
`define LAB1_IMUL_INT_MUL_ALT_V

`include "vc/arithmetic.v"
`include "vc/muxes.v"
`include "vc/trace.v"

module lab1_imul_IntMulTrailingZero
(
  input  logic [31:0] in,
  output logic [4:0]  trailing_zeros
);

  always_comb begin
    trailing_zeros = 5'd0;
    for ( int i = 0; i < 32; i++ ) begin
      if ( in[i] ) begin
        trailing_zeros = i[4:0];
        break;
      end
    end
  end

endmodule

//=========================================================================
// Datapath
//=========================================================================

module lab1_imul_IntMulAltDpath
(
  input  logic        clk,
  input  logic        reset,

  input  logic [63:0] istream_msg,
  output logic [31:0] ostream_msg,

  // Control signals from the control unit

  input  logic        a_mux_sel,
  input  logic        b_mux_sel,
  input  logic        result_mux_sel,
  input  logic        result_en,

  // Status signals to the control unit

  output logic        b_is_zero,
  output logic [5:0]  shift_amount,

  // Internal values exported for line tracing

  output logic [31:0] a_reg_out,
  output logic [31:0] b_reg_out,
  output logic [31:0] result_reg_out
);

  //-----------------------------------------------------------------------
  // Determine how far to skip
  //-----------------------------------------------------------------------

  logic [4:0] trailing_zeros;

  lab1_imul_IntMulTrailingZero trailing_zero
  (
    .in             (b_reg_out),
    .trailing_zeros (trailing_zeros)
  );

  assign b_is_zero = (b_reg_out == 32'b0);

  // Add 1 to the number of trailing zeros

  assign shift_amount = {1'b0,trailing_zeros} + 6'd1;

  //-----------------------------------------------------------------------
  // A operand path
  //-----------------------------------------------------------------------

  logic [31:0] a_mux_out;
  logic [31:0] a_skip_out;
  logic [31:0] a_shift_out;

  vc_Mux2#(32) a_mux
  (
    .in0 (istream_msg[63:32]),
    .in1 (a_shift_out),
    .sel (a_mux_sel),
    .out (a_mux_out)
  );

  always_ff @( posedge clk ) begin
    if ( reset ) a_reg_out <= 32'b0;
    else         a_reg_out <= a_mux_out;
  end

  // First skip the trailing zeros. This value feeds the result adder.

  assign a_skip_out = a_reg_out << trailing_zeros;

  // Then shift past the set bit that was just added. This value feeds
  // back into the A register for the next iteration.

  assign a_shift_out = a_skip_out << 1;

  //-----------------------------------------------------------------------
  // B operand path
  //-----------------------------------------------------------------------

  logic [31:0] b_mux_out;
  logic [31:0] b_shift_out;

  vc_Mux2#(32) b_mux
  (
    .in0 (istream_msg[31:0]),
    .in1 (b_shift_out),
    .sel (b_mux_sel),
    .out (b_mux_out)
  );

  always_ff @( posedge clk ) begin
    if ( reset ) b_reg_out <= 32'b0;
    else         b_reg_out <= b_mux_out;
  end

  // Shift B past the trailing zeros and the set bit that was just added

  assign b_shift_out = b_reg_out >> shift_amount;

  //-----------------------------------------------------------------------
  // Result path
  //-----------------------------------------------------------------------

  logic [31:0] add_out;
  logic [31:0] result_mux_out;

  assign add_out = a_skip_out + result_reg_out;

  vc_Mux2#(32) result_mux
  (
    .in0 (32'b0),
    .in1 (add_out),
    .sel (result_mux_sel),
    .out (result_mux_out)
  );

  always_ff @( posedge clk ) begin
    if      ( reset )     result_reg_out <= 32'b0;
    else if ( result_en ) result_reg_out <= result_mux_out;
  end

  assign ostream_msg = result_reg_out;

endmodule

//=========================================================================
// Control Unit
//=========================================================================

module lab1_imul_IntMulAltCtrl
(
  input  logic       clk,
  input  logic       reset,

  input  logic       istream_val,
  output logic       istream_rdy,

  output logic       ostream_val,
  input  logic       ostream_rdy,

  // Status signals from the datapath

  input  logic       b_is_zero,
  input  logic [5:0] shift_amount,

  // Control signals to the datapath

  output logic       a_mux_sel,
  output logic       b_mux_sel,
  output logic       result_mux_sel,
  output logic       result_en,

  // Internal values exported for line tracing

  output logic [1:0] status,
  output logic [5:0] counter
);

  localparam logic [1:0] IDLE = 2'd0;
  localparam logic [1:0] CALC = 2'd1;
  localparam logic [1:0] DONE = 2'd2;

  logic [1:0] status_next;
  logic [5:0] counter_next;

  //-----------------------------------------------------------------------
  // State elements
  //-----------------------------------------------------------------------

  always_ff @( posedge clk ) begin
    if ( reset ) begin
      status  <= IDLE;
      counter <= 6'd0;
    end
    else begin
      status  <= status_next;
      counter <= counter_next;
    end
  end

  //-----------------------------------------------------------------------
  // State transitions
  //-----------------------------------------------------------------------

  always_comb begin
    status_next = status;

    case ( status )
      IDLE: if ( istream_val ) status_next = CALC;
      CALC: begin
        if ( b_is_zero || (counter == 6'd32) ) status_next = DONE;
      end
      DONE: if ( ostream_rdy ) status_next = IDLE;
      default:                 status_next = IDLE;
    endcase
  end

  //-----------------------------------------------------------------------
  // State outputs
  //-----------------------------------------------------------------------

  always_comb begin
    istream_rdy    = 1'b0;
    ostream_val    = 1'b0;
    a_mux_sel      = 1'b0;
    b_mux_sel      = 1'b0;
    result_mux_sel = 1'b0;
    result_en      = 1'b0;
    counter_next   = counter;

    case ( status )
      IDLE: begin
        istream_rdy  = 1'b1;
        result_en    = 1'b1;
        counter_next = 6'd0;
      end

      CALC: begin
        a_mux_sel      = 1'b1;
        b_mux_sel      = 1'b1;
        result_mux_sel = 1'b1;

        if ( !b_is_zero && (counter < 6'd32) ) begin
          result_en    = 1'b1;
          counter_next = counter + shift_amount;
        end
      end

      DONE: begin
        ostream_val = 1'b1;
      end

      default: begin
        counter_next = 6'd0;
      end
    endcase
  end

endmodule

//=========================================================================
// Integer Multiplier Variable-Latency Implementation
//=========================================================================

module lab1_imul_IntMulAlt
(
  input  logic        clk,
  input  logic        reset,

  input  logic        istream_val,
  output logic        istream_rdy,
  input  logic [63:0] istream_msg,

  output logic        ostream_val,
  input  logic        ostream_rdy,
  output logic [31:0] ostream_msg
);

  // Control/status connections

  logic       a_mux_sel;
  logic       b_mux_sel;
  logic       result_mux_sel;
  logic       result_en;
  logic       b_is_zero;
  logic [5:0] shift_amount;

  // Internal values used by line tracing

  logic [1:0]  status;
  logic [5:0]  counter;
  logic [31:0] a_reg_out;
  logic [31:0] b_reg_out;
  logic [31:0] result_reg_out;

  lab1_imul_IntMulAltCtrl ctrl
  (
    .clk            (clk),
    .reset          (reset),
    .istream_val    (istream_val),
    .istream_rdy    (istream_rdy),
    .ostream_val    (ostream_val),
    .ostream_rdy    (ostream_rdy),
    .b_is_zero      (b_is_zero),
    .shift_amount   (shift_amount),
    .a_mux_sel      (a_mux_sel),
    .b_mux_sel      (b_mux_sel),
    .result_mux_sel (result_mux_sel),
    .result_en      (result_en),
    .status         (status),
    .counter        (counter)
  );

  lab1_imul_IntMulAltDpath dpath
  (
    .clk            (clk),
    .reset          (reset),
    .istream_msg    (istream_msg),
    .ostream_msg    (ostream_msg),
    .a_mux_sel      (a_mux_sel),
    .b_mux_sel      (b_mux_sel),
    .result_mux_sel (result_mux_sel),
    .result_en      (result_en),
    .b_is_zero      (b_is_zero),
    .shift_amount   (shift_amount),
    .a_reg_out      (a_reg_out),
    .b_reg_out      (b_reg_out),
    .result_reg_out (result_reg_out)
  );

  //----------------------------------------------------------------------
  // Line Tracing
  //----------------------------------------------------------------------

  `ifndef SYNTHESIS

  localparam logic [1:0] IDLE = 2'd0;
  localparam logic [1:0] CALC = 2'd1;
  localparam logic [1:0] DONE = 2'd2;

  logic [`VC_TRACE_NBITS-1:0] str;
  `VC_TRACE_BEGIN
  begin

    $sformat( str, "%x", istream_msg );
    vc_trace.append_val_rdy_str( trace_str, istream_val, istream_rdy, str );

    vc_trace.append_str( trace_str, "(" );

    case ( status )
      IDLE:    vc_trace.append_str( trace_str, "IDLE " );
      CALC:    vc_trace.append_str( trace_str, "CALC " );
      DONE:    vc_trace.append_str( trace_str, "DONE " );
      default: vc_trace.append_str( trace_str, "UNKN " );
    endcase

    $sformat( str, "c=%02d s=%02d a=%x b=%x r=%x",
              counter, shift_amount, a_reg_out, b_reg_out,
              result_reg_out );
    vc_trace.append_str( trace_str, str );

    vc_trace.append_str( trace_str, ")" );

    $sformat( str, "%x", ostream_msg );
    vc_trace.append_val_rdy_str( trace_str, ostream_val, ostream_rdy, str );

  end
  `VC_TRACE_END

  `endif /* SYNTHESIS */

endmodule

`endif /* LAB1_IMUL_INT_MUL_ALT_V */

"""
==========================================================================
ProcFL
==========================================================================
TinyRV2 FL processor

Author : Shunning Jiang, Peitian Pan, Christopher Batten
  Date : Sep 12, 2022
"""

from copy import deepcopy

from pymtl3 import *
from pymtl3.extra import clone_deepcopy
from pymtl3.stdlib.stream.ifcs import IStreamIfc, OStreamIfc
from pymtl3.stdlib.stream      import IStreamDeqAdapterFL, OStreamEnqAdapterFL
from pymtl3.stdlib.mem.ifcs    import MemRequesterIfc
from pymtl3.stdlib.mem         import mk_mem_msg, MemRequesterAdapterFL

from lab2_proc.tinyrv2_encoding import TinyRV2Inst, disassemble_inst

class RegisterFile(object):

  def __init__( self, nregs ):
    self.regs = [ b32(0) for i in range(nregs) ]

  def __getitem__( self, idx ):
    return self.regs[idx]

  def __setitem__( self, idx, value ):
    if idx != 0:
      self.regs[idx] = Bits32( int(value), trunc_int=True )

class ProcFL( Component ):

  def construct( s, num_cores=1 ):

    # Interface

    req_class, resp_class = mk_mem_msg( 8, 32, 32 )

    s.proc2mngr   = OStreamIfc( Bits32 )
    s.mngr2proc   = IStreamIfc( Bits32 )

    s.imem        = MemRequesterIfc( req_class, resp_class )
    s.dmem        = MemRequesterIfc( req_class, resp_class )

    s.core_id     = InPort(32)
    s.commit_inst = OutPort()
    s.stats_en    = OutPort()

    # Adapters

    s.proc2mngr_q = OStreamEnqAdapterFL( Bits32 )
    s.mngr2proc_q = IStreamDeqAdapterFL( Bits32 )

    connect( s.mngr2proc, s.mngr2proc_q.istream )
    connect( s.proc2mngr_q.ostream, s.proc2mngr )

    s.imem_adapter = MemRequesterAdapterFL( req_class, resp_class )
    s.dmem_adapter = MemRequesterAdapterFL( req_class, resp_class )

    connect( s.imem, s.imem_adapter.requester )
    connect( s.dmem, s.dmem_adapter.requester )

    # Internal data structures

    s.PC = b32( 0x200 )

    s.R = RegisterFile(32)
    s.raw_inst = None

    # We need to save the old PC for line tracing purposes, so that when
    # we do the line trace we are displaying the PC of the current
    # instruction and not the new PC

    s.PC_prev = b32( 0x200 )

    @update_once
    def up_ProcFL():
      if s.reset:
        s.PC = b32( 0x200 )
        return

      s.commit_inst @= 0

      try:
        s.PC_prev  = deepcopy(s.PC)
        s.raw_inst = s.imem_adapter.read( s.PC, 4 ) # line trace

        inst = TinyRV2Inst( s.raw_inst )
        inst_name = inst.name

        if   inst_name == "nop":
          s.PC += 4
        elif inst_name == "add":
          s.R[inst.rd] = s.R[inst.rs1] + s.R[inst.rs2]
          s.PC += 4
        elif inst_name == "sub":
          s.R[inst.rd] = s.R[inst.rs1] - s.R[inst.rs2]
          s.PC += 4
        elif inst_name == "sll":
          s.R[inst.rd] = s.R[inst.rs1] << (s.R[inst.rs2].uint() & 0x1F)
          s.PC += 4
        elif inst_name == "slt":
          s.R[inst.rd] = s.R[inst.rs1].int() < s.R[inst.rs2].int()
          s.PC += 4
        elif inst_name == "xor":
          s.R[inst.rd] = s.R[inst.rs1] ^ s.R[inst.rs2]
          s.PC += 4
        elif inst_name == "srl":
          s.R[inst.rd] = s.R[inst.rs1] >> (s.R[inst.rs2].uint() & 0x1F)
          s.PC += 4
        elif inst_name == "sra":
          s.R[inst.rd] = s.R[inst.rs1].int() >> (s.R[inst.rs2].uint() & 0x1F) # sra
          s.PC += 4
        elif inst_name == "or":
          s.R[inst.rd] = s.R[inst.rs1] | s.R[inst.rs2]
          s.PC += 4
        elif inst_name == "and":
          s.R[inst.rd] = s.R[inst.rs1] & s.R[inst.rs2]
          s.PC += 4
        elif inst_name == "mul":
          s.R[inst.rd] = s.R[inst.rs1] * s.R[inst.rs2]
          s.PC += 4

        elif inst_name == "addi":
          s.R[inst.rd] = s.R[inst.rs1] + sext( inst.i_imm, 32 )
          s.PC += 4
        elif inst_name == "slti":
          s.R[inst.rd] = s.R[inst.rs1].int() < inst.i_imm.int()
          s.PC += 4
        elif inst_name == "ori":
          s.R[inst.rd] = s.R[inst.rs1] | sext( inst.i_imm, 32 )
          s.PC += 4
        elif inst_name == "slli":
          s.R[inst.rd] = s.R[inst.rs1] << inst.shamt.uint()
          s.PC += 4
        elif inst_name == "srai":
          s.R[inst.rd] = Bits32( s.R[inst.rs1].int() >> inst.shamt.uint() )
          s.PC += 4

        elif inst_name == "lui":
          s.R[inst.rd] = inst.u_imm
          s.PC += 4
        elif inst_name == "auipc":
          s.R[inst.rd] = inst.u_imm + s.PC
          s.PC += 4

        elif inst_name == "lw":
          addr = s.R[inst.rs1] + sext( inst.i_imm, 32 )
          s.R[inst.rd] = s.dmem_adapter.read( addr, 4 )
          s.PC += 4
        elif inst_name == "sw":
          addr = s.R[inst.rs1] + sext( inst.s_imm, 32 )
          s.dmem_adapter.write( addr, 4, s.R[inst.rs2] )
          s.PC += 4

        elif inst_name == "bne":
          if s.R[inst.rs1] != s.R[inst.rs2]:
            s.PC = s.PC + sext( inst.b_imm, 32 )
          else:
            s.PC += 4
        elif inst_name == "beq":
          if s.R[inst.rs1] == s.R[inst.rs2]:
            s.PC = s.PC + sext( inst.b_imm, 32 )
          else:
            s.PC += 4
        elif inst_name == "blt":
          if s.R[inst.rs1].int() < s.R[inst.rs2].int():
            s.PC = s.PC + sext( inst.b_imm, 32 )
          else:
            s.PC += 4
        elif inst_name == "bltu":
          if s.R[inst.rs1] < s.R[inst.rs2]:
            s.PC = s.PC + sext( inst.b_imm, 32 )
          else:
            s.PC += 4

        elif inst_name == "jal":
          s.R[inst.rd] = s.PC + 4
          s.PC = s.PC + sext( inst.j_imm, 32 )

        elif inst_name == "jalr":
          temp = s.R[inst.rs1] + sext( inst.i_imm, 32 )
          s.R[inst.rd] = s.PC + 4
          s.PC = temp & 0xFFFFFFFE

        elif inst_name == "csrw":
          if   inst.csrnum == 0x7C0:
            if not s.proc2mngr_q.enq.rdy():
              return
            s.proc2mngr_q.enq( s.R[inst.rs1] )
          elif inst.csrnum == 0x7C1:
            s.stats_en @= trunc(s.R[inst.rs1],1)
          else:
            raise TinyRV2Semantics.IllegalInstruction(
              "Unrecognized CSR register ({}) for csrw at PC={}" \
                .format(inst.csrnum.uint(),s.PC) )
          s.PC += 4

        elif inst_name == "csrr":
          if   inst.csrnum == 0xFC0:
            if not s.mngr2proc_q.deq.rdy():
              return
            s.R[inst.rd] = s.mngr2proc_q.deq()
          elif inst.csrnum == 0xFC1:
            s.R[inst.rd] = num_cores
          elif inst.csrnum == 0xF14:
            s.R[inst.rd] = s.core_id
          else:
            raise TinyRV2Semantics.IllegalInstruction(
              "Unrecognized CSR register ({}) for csrr at PC={}" \
                .format(inst.csrnum.uint(),s.PC) )
          s.PC += 4

      except:
        print( "Unexpected error at PC={:0>8s}!".format( str(s.PC) ) )
        raise

      s.commit_inst @= 1

  #-----------------------------------------------------------------------
  # line_trace
  #-----------------------------------------------------------------------

  def line_trace( s ):
    if s.commit_inst:
      return "{:0>8s} {: <24}".format( str(s.PC_prev), disassemble_inst( s.raw_inst ) )
    return "{}".format( "#".ljust(33) )

