// Control Unit
//=========================================================================

module lab1_imul_IntMulAltCtrl
(
  input  logic       clk,
  input  logic       reset,

  input  logic       istream_val,
  output logic       istream_rdy,

  output logic       ostream_val,
  input  logic       ostream_rdy,

  // Status signals from the datapath

  input  logic       b_is_zero,
  input  logic [5:0] shift_amount,

  // Control signals to the datapath

  output logic       a_mux_sel,
  output logic       b_mux_sel,
  output logic       result_mux_sel,
  output logic       result_en,

  // Internal values exported for line tracing

  output logic [1:0] status,
  output logic [5:0] counter
);

  localparam logic [1:0] IDLE = 2'd0;
  localparam logic [1:0] CALC = 2'd1;
  localparam logic [1:0] DONE = 2'd2;

  logic [1:0] status_next;
  logic [5:0] counter_next;

  //-----------------------------------------------------------------------
  // State elements
  //-----------------------------------------------------------------------

  always_ff @( posedge clk ) begin
    if ( reset ) begin
      status  <= IDLE;
      counter <= 6'd0;
    end
    else begin
      status  <= status_next;
      counter <= counter_next;
    end
  end

  //-----------------------------------------------------------------------
  // State transitions
  //-----------------------------------------------------------------------

  always_comb begin
    status_next = status;

    case ( status )
      IDLE: if ( istream_val ) status_next = CALC;
      CALC: begin
        if ( b_is_zero || (counter == 6'd32) ) status_next = DONE;
      end
      DONE: if ( ostream_rdy ) status_next = IDLE;
      default:                 status_next = IDLE;
    endcase
  end

  //-----------------------------------------------------------------------
  // State outputs
  //-----------------------------------------------------------------------

  always_comb begin
    istream_rdy    = 1'b0;
    ostream_val    = 1'b0;
    a_mux_sel      = 1'b0;
    b_mux_sel      = 1'b0;
    result_mux_sel = 1'b0;
    result_en      = 1'b0;
    counter_next   = counter;

    case ( status )
      IDLE: begin
        istream_rdy  = 1'b1;
        result_en    = 1'b1;
        counter_next = 6'd0;
      end

      CALC: begin
        a_mux_sel      = 1'b1;
        b_mux_sel      = 1'b1;
        result_mux_sel = 1'b1;

        if ( !b_is_zero && (counter < 6'd32) ) begin
          result_en    = 1'b1;
          counter_next = counter + shift_amount;
        end
      end

      DONE: begin
        ostream_val = 1'b1;
      end

      default: begin
        counter_next = 6'd0;
      end
    endcase
  end

endmodule

//=========================================================================
// Integer Multiplier Variable-Latency Implementation
//=========================================================================

module lab1_imul_IntMulAlt
(
  input  logic        clk,
  input  logic        reset,

  input  logic        istream_val,
  output logic        istream_rdy,
  input  logic [63:0] istream_msg,

  output logic        ostream_val,
  input  logic        ostream_rdy,
  output logic [31:0] ostream_msg
);

  // Control/status connections

  logic       a_mux_sel;
  logic       b_mux_sel;
  logic       result_mux_sel;
  logic       result_en;
  logic       b_is_zero;
  logic [5:0] shift_amount;

  // Internal values used by line tracing

  logic [1:0]  status;
  logic [5:0]  counter;
  logic [31:0] a_reg_out;
  logic [31:0] b_reg_out;
  logic [31:0] result_reg_out;

  lab1_imul_IntMulAltCtrl ctrl
  (
    .clk            (clk),
    .reset          (reset),
    .istream_val    (istream_val),
    .istream_rdy    (istream_rdy),
    .ostream_val    (ostream_val),
    .ostream_rdy    (ostream_rdy),
    .b_is_zero      (b_is_zero),
    .shift_amount   (shift_amount),
    .a_mux_sel      (a_mux_sel),
    .b_mux_sel      (b_mux_sel),
    .result_mux_sel (result_mux_sel),
    .result_en      (result_en),
    .status         (status),
    .counter        (counter)
  );

  lab1_imul_IntMulAltDpath dpath
  (
    .clk            (clk),
    .reset          (reset),
    .istream_msg    (istream_msg),
    .ostream_msg    (ostream_msg),
    .a_mux_sel      (a_mux_sel),
    .b_mux_sel      (b_mux_sel),
    .result_mux_sel (result_mux_sel),
    .result_en      (result_en),
    .b_is_zero      (b_is_zero),
    .shift_amount   (shift_amount),
    .a_reg_out      (a_reg_out),
    .b_reg_out      (b_reg_out),
    .result_reg_out (result_reg_out)
  );

  //----------------------------------------------------------------------
  // Line Tracing
  //----------------------------------------------------------------------

  `ifndef SYNTHESIS

  localparam logic [1:0] IDLE = 2'd0;
  localparam logic [1:0] CALC = 2'd1;
  localparam logic [1:0] DONE = 2'd2;

  logic [`VC_TRACE_NBITS-1:0] str;
  `VC_TRACE_BEGIN
  begin

    $sformat( str, "%x", istream_msg );
    vc_trace.append_val_rdy_str( trace_str, istream_val, istream_rdy, str );

    vc_trace.append_str( trace_str, "(" );

    case ( status )
      IDLE:    vc_trace.append_str( trace_str, "IDLE " );
      CALC:    vc_trace.append_str( trace_str, "CALC " );
      DONE:    vc_trace.append_str( trace_str, "DONE " );
      default: vc_trace.append_str( trace_str, "UNKN " );
    endcase

    $sformat( str, "c=%02d s=%02d a=%x b=%x r=%x",
              counter, shift_amount, a_reg_out, b_reg_out,
              result_reg_out );
    vc_trace.append_str( trace_str, str );

    vc_trace.append_str( trace_str, ")" );

    $sformat( str, "%x", ostream_msg );
    vc_trace.append_val_rdy_str( trace_str, ostream_val, ostream_rdy, str );

  end
  `VC_TRACE_END

  `endif /* SYNTHESIS */

endmodule

`endif /* LAB1_IMUL_INT_MUL_ALT_V */
